#!/usr/bin/env node
// Builds every generated file of the skill from its sources:
//   engine/src/*.js            → engine/bizos-charts.js (single offline file)
//   engine registry            → references/chart-index.json
//   examples/specs/*.json      → templates/gallery.zh.html, templates/gallery.en.html
//   examples/reports/*.json    → templates/reports/<layout>.<lang>.html
//   engine THEME               → color-presets.js, mono-tokens.js (compatibility views)
// Usage: node scripts/build.mjs [--engine-only] [--check]
//   --check  rebuild in memory and fail if any generated file is stale.
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { createRequire } from 'node:module';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const require = createRequire(import.meta.url);
const args = new Set(process.argv.slice(2));
const check = args.has('--check');
const outputs = new Map();
const write = (rel, content) => outputs.set(rel, content);

function buildEngine() {
  const dir = path.join(root, 'engine/src');
  const files = fs.readdirSync(dir).filter((f) => f.endsWith('.js')).sort();
  const body = files.map((f) => `/* ── ${f} ── */\n` + fs.readFileSync(path.join(dir, f), 'utf8')).join('\n');
  const version = (body.match(/BC\.version = '([^']+)'/) || [])[1] || '0.0.0';
  const src = `/*! BizOS Charts engine ${version} — research-grade exhibits, zero dependencies, offline.\n` +
    ` *  Generated by scripts/build.mjs from engine/src/*.js. Edit the sources, then rebuild. */\n` +
    `(function (root, factory) {\n  var api = factory();\n  if (typeof module === 'object' && module.exports) module.exports = api;\n  else root.BizosCharts = api;\n})(typeof globalThis !== 'undefined' ? globalThis : this, function () {\n'use strict';\n` +
    body + `\nreturn BC;\n});\n`;
  write('engine/bizos-charts.js', src);
  return src;
}

function loadEngine(src) {
  const m = { exports: {} };
  // eslint-disable-next-line no-new-func
  new Function('module', 'exports', src)(m, m.exports);
  return m.exports;
}

function readJSON(file) { return JSON.parse(fs.readFileSync(file, 'utf8')); }

function trimSample(spec) {
  const out = JSON.parse(JSON.stringify(spec));
  delete out.wide;
  const cut = (arr) => (Array.isArray(arr) && arr.length > 3 ? arr.slice(0, 3) : arr);
  if (Array.isArray(out.data)) out.data = cut(out.data);
  if (Array.isArray(out.values)) out.values = cut(out.values).map((r) => (Array.isArray(r) ? r.slice(0, 3) : r));
  if (out.rows && Array.isArray(out.rows.values)) out.rows.values = cut(out.rows.values);
  if (out.cols && Array.isArray(out.cols.values)) out.cols.values = cut(out.cols.values);
  if (Array.isArray(out.rows)) out.rows = cut(out.rows);
  if (Array.isArray(out.nodes)) out.nodes = cut(out.nodes);
  const zhOnly = (v) => {
    if (Array.isArray(v)) return v.map(zhOnly);
    if (v && typeof v === 'object') { const k = Object.keys(v); if (k.length && k.every((x) => x === 'zh' || x === 'en')) return v.zh; return Object.fromEntries(Object.entries(v).map(([a, b]) => [a, zhOnly(b)])); }
    return v;
  };
  return zhOnly(out);
}

function buildDocs(BC) {
  const cat = BC.catalog(), fam = BC.families, samples = Object.fromEntries(gallerySpecs().map(({ file, spec }) => [file.slice(0, 3), spec]));
  const by = {}; cat.forEach((c) => (by[c.family] = by[c.family] || []).push(c));
  let md = `# BizOS 图表目录 · ${cat.length} 种\n\n` +
    `> 由 \`scripts/build.mjs\` 根据引擎注册表生成，勿手改。选型方法见 [chart-selection](references/chart-selection.md)；` +
    `字段契约与示例见 [spec-reference](references/spec-reference.md)；视觉与口径规范见 [house-style](references/house-style.md)。\n` +
    `> 中英文样例：[templates/gallery.zh.html](templates/gallery.zh.html) · [templates/gallery.en.html](templates/gallery.en.html)。\n`;
  for (const f of Object.keys(fam)) {
    if (!by[f]) continue;
    md += `\n## ${f} · ${fam[f].zh}（${by[f].length}）\n\n| 编号 | 图表 | 回答的问题 | 适用 | 不适用 / 改用 |\n|---|---|---|---|---|\n`;
    for (const c of by[f]) md += `| ${c.id} | ${c.name.zh}<br>${c.name.en} | ${c.question.zh} | ${c.use.zh} | ${c.avoid.zh} |\n`;
  }
  write('catalog.md', md);

  let ref = `# 规格参考 · Spec reference\n\n> 由 \`scripts/build.mjs\` 根据引擎注册表与 \`examples/specs\` 生成，勿手改。完整样例数据见 \`examples/specs/<编号>-*.json\`。\n\n` +
`## 通用字段（所有图表）

| 字段 | 必填 | 说明 |
|---|---|---|
| \`type\` | 是 | 图表编号，如 \`"T03"\` |
| \`lang\` | 否 | \`"zh"\`（默认）或 \`"en"\`；同一交付只用一种语言 |
| \`title\` | 是 | 一句话结论（不是图名），数字必须能从本图数据核对 |
| \`subtitle\` | 建议 | 指标、单位、期间，如“年度营业收入（百万元），2020A–2027E” |
| \`unit\` | 视图而定 | 数值单位，如“百万元”“件”；\`format\` 为 percent / pp / multiple / index / bps / currency 时可省 |
| \`format\` | 否 | \`"number:1"\` \`"integer"\` \`"percent:1"\` \`"pp"\` \`"multiple"\` \`"currency"\` 或 \`{type, decimals, prefix, suffix, scale, negative:"parens"}\` |
| \`source\` | 是 | 资料来源；用户数据写“用户提供”或文件名 |
| \`notes\` | 否 | 注释数组：口径、剔除项、估算方法 |
| \`data\` | 是 | 行数组（每行一条记录）；V02、V04、K01、K04、S07、E09、B07 的结构见各自说明 |
| \`no\` | 否 | 图表编号；页面与报告自动编号 |
| \`highlight\` | 否 | 需要突出的实体名数组；其余自动退为灰色 |
| \`colors\` | 否 | \`{系列名: "#hex"}\`，仅在品牌或语义要求时使用 |
| \`palette\` | 否 | \`"research"\`（默认）、\`"mono"\`（黑白打印）或 \`{primary:"#hex"}\`（品牌主色） |
| \`names\` | 否 | \`{字段名: 显示名}\` |
| \`table\` / \`legend\` | 否 | 设为 \`false\` 关闭数据表 / 图例 |
| \`width\` / \`height\` | 否 | 仅静态导出时使用；网页内按容器宽度自动重绘 |

**数值约定**：百分比一律以百分数存储（12.5 表示 12.5%）；缺失值留 \`null\`，不得补 0；无意义值写 \`"n.m."\`。
**期间约定**：\`2025\`、\`2025-03\`、\`2025-03-14\`、\`2025Q1\`、\`2026E\`；以 E 结尾的期间按预测值绘制（斜线填充 / 虚线），E 之后不得再出现实际期。
**通用选项**：\`refLines:[{value, label, axis:"value"|"x"}]\`（C01 支持 \`"median"\` / \`"mean"\`），\`bands:[{from, to, label}]\`，\`annotations:[{x, y, text}]\`，\`estimateFrom\`，\`yDomain:[min,max]\`（折线类）。保留字：type、lang、title、subtitle、unit、format、notes、source、data、no、palette、highlight、colors、names、width、height、table、legend，不得用作字段映射名。
**统计量**：E、B 族的检验、区间、拟合与合并估计由引擎计算，\`render()\` 结果和 \`render.mjs\` 输出的 \`stats\` 字段给出全部数值，标题与正文直接引用；P 值格式与科研图规范见 [house-style](house-style.md) 第 10 节。
`;
  for (const f of Object.keys(fam)) {
    if (!by[f]) continue;
    ref += `\n## ${f} · ${fam[f].zh} / ${fam[f].en}\n`;
    for (const c of by[f]) {
      ref += `\n### ${c.id} ${c.name.zh} · ${c.name.en}\n\n- 回答：${c.question.zh}\n- 适用：${c.use.zh}\n- 不适用：${c.avoid.zh}\n- 输出：${c.output === 'html' ? 'HTML 表格/指标卡' : 'SVG'}${c.needsUnit ? '' : '；可不填 unit'}\n- 字段：\n`;
      for (const fd of c.fields) ref += `  - \`${fd.key}\`（${fd.role}${fd.required ? '，必填' : '，可选'}）：${fd.desc.zh}\n`;
      if (c.options.length) ref += `- 选项：${c.options.map((o) => '`' + o + '`').join('、')}\n`;
      const sample = samples[c.id];
      if (sample) ref += `- 示例（数据截取前 3 行）：\n\n\`\`\`json\n${JSON.stringify(trimSample(sample))}\n\`\`\`\n`;
    }
  }
  write('references/spec-reference.md', ref);
}

function buildIndex(BC) {
  const catalog = BC.catalog();
  write('references/chart-index.json', JSON.stringify({ schema: 'bizos.chart-index.v2', engine: BC.version, families: BC.families, charts: catalog }, null, 1) + '\n');
}

function gallerySpecs() {
  const dir = path.join(root, 'examples/specs');
  if (!fs.existsSync(dir)) return [];
  const fam = 'TCSDRVHGKPMEB';
  const rank = (f) => fam.indexOf(f[0]) * 100 + parseInt(f.slice(1, 3), 10);
  return fs.readdirSync(dir).filter((f) => f.endsWith('.json')).sort((a, b) => rank(a) - rank(b) || a.localeCompare(b)).map((f) => ({ file: f, spec: readJSON(path.join(dir, f)) }));
}

function buildGallery(BC, engineSrc, lang) {
  const items = gallerySpecs();
  const fam = BC.families;
  const specs = items.map(({ spec }) => ({ ...spec, lang }));
  const many = BC.renderMany(specs, { width: 520, widthFor: (sp) => (sp.wide ? 1056 : 520), numbering: true });
  const issues = many.issues.filter((i) => i.level === 'error');
  if (issues.length) throw new Error('gallery spec errors: ' + JSON.stringify(issues, null, 1));
  const byFam = {};
  many.results.forEach((r, i) => { const f = r.type[0]; (byFam[f] = byFam[f] || []).push({ r, spec: specs[i] }); });
  const cat = Object.fromEntries(BC.catalog().map((c) => [c.id, c]));
  const order = Object.keys(fam).filter((f) => byFam[f]);
  const en = lang === 'en';
  let body = '<main class="bz-page"><div class="bz-sheet">' +
    `<div class="bz-mast"><span><b>BIZOS RESEARCH</b> · ${en ? 'Chart atlas' : '图表图谱'}</span><span>${en ? 'Engine' : '引擎'} ${BC.version}</span></div>` +
    `<h1 class="bz-h1">${en ? `${many.results.length} exhibit types, one house style` : `${many.results.length} 种图表，一套研报规范`}</h1>` +
    `<p class="bz-lede">${en ? 'Every exhibit below is rendered by the offline engine from a JSON spec in examples/specs. Data are illustrative. Each card shows the chart ID, the question it answers and the rule checks it passed.' : '以下每张图都由离线引擎从 examples/specs 中的 JSON 规格渲染，数据为示例。每张卡片标注图表编号、回答的问题，并已通过规范检查。'}</p>`;
  order.forEach((f, k) => {
    body += `<div class="bz-sec"><h2>${String(k + 1).padStart(2, '0')} ${fam[f][lang]}</h2><span>${byFam[f].map((x) => x.r.type).join(' · ')}</span></div><div class="bz-grid">`;
    byFam[f].forEach(({ r, spec }) => {
      const meta = cat[r.type];
      const warn = r.issues.filter((i) => i.level === 'warning').map((i) => i.code).join(', ');
      body += `<div${spec.wide ? ' class="bz-wide"' : ''}>${r.html}<div class="bz-meta"><b>${r.type}</b> ${meta.name[lang]} — ${meta.question[lang]}${warn ? ' · ' + warn : ''}</div></div>`;
    });
    body += '</div>';
  });
  body += `<div class="bz-pagefoot"><span>BIZOS RESEARCH</span><span>${en ? 'Illustrative data; not investment advice.' : '示例数据，仅用于展示图表规范。'}</span></div></div></main>`;
  const html = BC.documentHTML({ lang, title: en ? 'BizOS Charts — atlas' : 'BizOS Charts 图表图谱', body, specs: specs.map((s, i) => ({ ...s, no: many.results[i].no })), colorMap: {}, engineSource: engineSrc });
  write(`templates/gallery.${lang}.html`, html);
}

function buildReports(BC, engineSrc) {
  const dir = path.join(root, 'examples/reports');
  if (!fs.existsSync(dir) || typeof BC.report !== 'function') return;
  const specDir = path.join(root, 'examples/specs');
  const resolveRefs = (node) => {
    if (Array.isArray(node)) return node.map(resolveRefs);
    if (node && typeof node === 'object') {
      if (typeof node.ref === 'string' && Object.keys(node).every((k) => k === 'ref' || k === 'override')) {
        const base = readJSON(path.join(specDir, node.ref + '.json'));
        delete base.wide;
        return { ...base, ...(node.override || {}) };
      }
      return Object.fromEntries(Object.entries(node).map(([k, v]) => [k, resolveRefs(v)]));
    }
    return node;
  };
  for (const f of fs.readdirSync(dir).filter((x) => x.endsWith('.json')).sort()) {
    const spec = resolveRefs(readJSON(path.join(dir, f)));
    for (const lang of spec.langs || [spec.lang || 'zh']) {
      const r = BC.report({ ...spec, lang }, { engineSource: engineSrc });
      const errors = r.issues.filter((i) => i.level === 'error');
      if (errors.length) throw new Error(`report ${f} (${lang}) errors: ` + JSON.stringify(errors, null, 1));
      write(`templates/reports/${spec.layout}.${lang}.html`, r.html);
    }
  }
}

function buildTokens(BC) {
  const T = BC.theme;
  const header = (name) => `/* ${name} — generated by scripts/build.mjs from engine/src/20-theme.js.\n   Compatibility view for skills that read colour/typography tokens directly.\n   The engine theme is the only source of truth; do not edit by hand. */\n`;
  const exec = { name: 'executive', cn: '研报标准色', logic: 'categorical', BG: T.page, CARD: T.card, TXT: T.ink, MUT: T.muted, LAB: T.ink2, GRID: T.grid,
    DATA: T.primary, DATA2: T.series[1], HERO: T.series[1], SER: T.series, CAT4: T.series.slice(0, 4), CAT3: T.series.slice(0, 3), RAMP: T.seq, DIVERGING: T.div,
    GOOD: T.good, BAD: T.bad, DIM: T.dim, MARKET: BC.market };
  const mono = { name: 'mono', cn: '黑白打印', logic: 'ordinal', BG: T.page, CARD: T.card, TXT: T.ink, MUT: T.muted, LAB: T.ink2, GRID: T.grid, DATA: T.mono[0], SER: T.mono, RAMP: T.mono.slice().reverse() };
  write('color-presets.js', header('COLOR PRESETS') +
    `(function (global) {\n  'use strict';\n  var EXECUTIVE = ${JSON.stringify(exec, null, 2).replace(/\n/g, '\n  ')};\n  var MONO = ${JSON.stringify(mono, null, 2).replace(/\n/g, '\n  ')};\n` +
    `  global.PRESETS = { EXECUTIVE: EXECUTIVE, RESEARCH: EXECUTIVE, MONO: MONO, list: ['executive', 'mono'],\n    get: function (n) { n = String(n).toLowerCase(); return n === 'mono' ? MONO : (n === 'executive' || n === 'research') ? EXECUTIVE : null; } };\n})(typeof window !== 'undefined' ? window : globalThis);\n`);
  const font = { family: T.font, bodyFamily: T.font, dataFamily: T.font, numeric: 'tabular-nums lining-nums', title: { size: T.size.title, weight: 600 }, sub: { size: T.size.sub, weight: 400 }, axis: { size: T.size.label, weight: 400 }, src: { size: T.size.small, weight: 400 }, kpi: { size: T.size.kpi, weight: 700 }, minChartText: 12 };
  write('mono-tokens.js', header('TYPOGRAPHY & NEUTRAL TOKENS') +
    `(function (global) {\n  'use strict';\n  global.MONO = ${JSON.stringify({ INK: T.ink, PAPER: T.page, CARD: T.card, MUTED: T.muted, FAINT: T.faint, GRID: T.grid, RULE: T.rule, L: T.mono, FONT: font, SHAPE: { cardRadius: 0, barRadius: 0 } }, null, 2).replace(/\n/g, '\n  ')};\n})(typeof window !== 'undefined' ? window : globalThis);\n`);
}

const engineSrc = buildEngine();
const BC = loadEngine(engineSrc);
if (!args.has('--engine-only')) {
  buildIndex(BC);
  buildDocs(BC);
  buildGallery(BC, engineSrc, 'zh');
  buildGallery(BC, engineSrc, 'en');
  buildReports(BC, engineSrc);
  buildTokens(BC);
}
let stale = [];
for (const [rel, content] of outputs) {
  const file = path.join(root, rel);
  const current = fs.existsSync(file) ? fs.readFileSync(file, 'utf8') : null;
  if (current === content) continue;
  if (check) { stale.push(rel); continue; }
  fs.mkdirSync(path.dirname(file), { recursive: true });
  fs.writeFileSync(file, content);
}
if (check && stale.length) { console.error('Stale generated files (run node scripts/build.mjs):\n  ' + stale.join('\n  ')); process.exit(1); }
console.log(JSON.stringify({ ok: true, engine: BC.version, types: BC.order().length, files: [...outputs.keys()], checked: check }));
